/* @lc app=leetcode id=2528 lang=kotlin */ class Solution { fun ok(pw: LongArray, r: Int, k: Int, x: Long): Boolean = LongArray(pw.size + 1).let { add -> generateSequence(Triple(0L, k.toLong(), 0)) { (cur, left, i) -> if (i == pw.size) null else (cur + add[i]).let { c1 -> maxOf(0L, x - pw[i] - c1).let { need -> if (need > left) Triple(c1, -1L, pw.size) else Triple(c1 + need, left - need, i + 1).also { add[minOf(pw.size, i + 2 * r + 1)] -= need } } } }.last().second >= 0 } fun maxPower(stations: IntArray, r: Int, k: Int): Long = stations.size.let { n -> stations.runningFold(0L) { s, v -> s + v }.let { pre -> LongArray(n) { i -> pre[minOf(n, i + r + 1)] - pre[maxOf(0, i - r)] }.let { pw -> generateSequence(0L to 20_000_000_000L) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { mid -> if (ok(pw, r, k, mid)) mid to hi else lo to mid - 1 } }.last().first } } } }